codeFiles.source:
#include <stdio.h>

int main(void)
{
    int age;
    float height;
    char section;

    printf("Enter your age: ");
    scanf("%d", &age);

    printf("Enter your height in metres: ");
    scanf("%f", &height);

    printf("Enter your section: ");
    scanf(" %c", &section);     // space skips the leftover Enter

    printf("Age %d, height %.2f m, section %c\n", age, height, section);
    return 0;
}

